from pathlib import Path
root = Path('/tmp/aigunner/ai-gunner-dev10')

# Replace GunnerArenaAdapter with rc4 version.
p = root / 'src/main/java/ai/gunner/integration/GunnerArenaAdapter.java'
p.write_text('''package ai.gunner.integration;\n\nimport net.minecraft.client.player.LocalPlayer;\nimport net.minecraft.core.registries.BuiltInRegistries;\nimport net.minecraft.resources.ResourceLocation;\nimport net.minecraft.world.item.ItemStack;\n\nimport java.lang.reflect.Constructor;\nimport java.lang.reflect.Field;\nimport java.lang.reflect.Method;\n\n/** Optional integration with Gunner Arena. Everything is reflective so AI Gunner still loads without it. */\npublic final class GunnerArenaAdapter {\n    private static final String SECONDARY = "jeg:semi_auto_pistol";\n    private static final String PRIMARY = "jeg:custom_smg";\n    private static final String UPGRADE_PRIMARY = "jeg:assault_rifle";\n    private static int buyCooldown;\n    private static int ammoGiveCooldown;\n    private static int ammoGiveWait;\n    private static ResourceLocation pendingAmmo;\n\n    private GunnerArenaAdapter() {}\n\n    public static void tick() {\n        if (buyCooldown > 0) buyCooldown--;\n        if (ammoGiveCooldown > 0) ammoGiveCooldown--;\n        if (ammoGiveWait > 0) ammoGiveWait--;\n    }\n\n    public static boolean waitingForAmmoGive() { return ammoGiveWait > 0; }\n\n    public static void clearAmmoGiveWait() {\n        ammoGiveWait = 0;\n        pendingAmmo = null;\n    }\n\n    public static boolean hasJegGun(LocalPlayer player) {\n        if (player == null) return false;\n        for (int i = 0; i < 9; i++) if (JegAdapter.isGun(player.getInventory().getItem(i))) return true;\n        return false;\n    }\n\n    public static boolean hasItem(LocalPlayer player, String id) {\n        if (player == null) return false;\n        ResourceLocation wanted = ResourceLocation.tryParse(id);\n        if (wanted == null) return false;\n        for (ItemStack stack : player.getInventory().items) {\n            if (!stack.isEmpty() && wanted.equals(BuiltInRegistries.ITEM.getKey(stack.getItem()))) return true;\n        }\n        return false;\n    }\n\n    /**\n     * Tries to obtain a sensible autonomous loadout through the arena's own BuyRequest.\n     * The server remains authoritative and rejects purchases if credits are insufficient.\n     */\n    public static boolean ensureBaselineLoadout(LocalPlayer player) {\n        if (player == null || buyCooldown > 0) return false;\n        String wanted;\n        if (!hasItem(player, SECONDARY)) wanted = SECONDARY;\n        else if (!hasItem(player, PRIMARY)) wanted = PRIMARY;\n        else if (!hasItem(player, UPGRADE_PRIMARY)) wanted = UPGRADE_PRIMARY;\n        else return false;\n        boolean sent = sendBuy(wanted);\n        buyCooldown = sent ? 80 : 120;\n        return sent;\n    }\n\n    /**\n     * OP/admin fast path: ask the server for exactly the ammo required by the selected gun.\n     * We do not assume permission. After one request AI waits briefly; if inventory did not change,\n     * CombatBrain falls back to physical ammo pickups/spawners. Long cooldown prevents command spam.\n     */\n    public static boolean tryGiveRequiredAmmo(LocalPlayer player, ItemStack gun) {\n        if (player == null || player.connection == null || !JegAdapter.isGun(gun)) return false;\n        if (ammoGiveWait > 0 || ammoGiveCooldown > 0) return false;\n        ResourceLocation ammo = JegAdapter.ammoItemId(gun);\n        if (ammo == null) return false;\n        try {\n            player.connection.sendCommand("give @s " + ammo + " 64");\n            pendingAmmo = ammo;\n            ammoGiveWait = 20;\n            ammoGiveCooldown = 400;\n            return true;\n        } catch (Throwable ignored) {\n            ammoGiveCooldown = 200;\n            return false;\n        }\n    }\n\n    public static boolean pendingAmmoArrived(LocalPlayer player, ItemStack gun) {\n        if (player == null || !JegAdapter.isGun(gun)) return false;\n        ResourceLocation wanted = JegAdapter.ammoItemId(gun);\n        if (wanted == null) return false;\n        if (pendingAmmo != null && !pendingAmmo.equals(wanted)) return false;\n        if (JegAdapter.reserveAmmo(player, gun) > 0) {\n            clearAmmoGiveWait();\n            return true;\n        }\n        return false;\n    }\n\n    private static boolean sendBuy(String weaponId) {\n        try {\n            Class<?> network = Class.forName("arena.forge.net.ArenaNetwork");\n            Field channelField = network.getField("CHANNEL");\n            Object channel = channelField.get(null);\n            if (channel == null) return false;\n            Class<?> request = Class.forName("arena.forge.net.ArenaNetwork$BuyRequest");\n            Constructor<?> ctor = request.getConstructor(String.class);\n            Object packet = ctor.newInstance(weaponId);\n            for (Method m : channel.getClass().getMethods()) {\n                if (m.getName().equals("sendToServer") && m.getParameterCount() == 1) {\n                    m.invoke(channel, packet);\n                    return true;\n                }\n            }\n        } catch (Throwable ignored) {}\n        return false;\n    }\n}\n''')

# CombatBrain: always enter RESUPPLY on empty gun, let resupply handle OP give -> spawner fallback.
p = root / 'src/main/java/ai/gunner/brain/CombatBrain.java'
s = p.read_text()
old = '''            if (JegAdapter.isGun(idleGun) && !JegAdapter.hasAmmo(idleGun) && JegAdapter.reserveAmmo(self, idleGun) <= 0\n                    && findAmmoDestination(mc, self, idleGun) != null) {\n                state = BotState.RESUPPLY;\n                resupply(mc, self, idleGun);\n                return;\n            }\n'''
new = '''            if (JegAdapter.isGun(idleGun) && !JegAdapter.hasAmmo(idleGun) && JegAdapter.reserveAmmo(self, idleGun) <= 0) {\n                state = BotState.RESUPPLY;\n                resupply(mc, self, idleGun);\n                return;\n            }\n'''
if old not in s:
    raise RuntimeError('rc4 idle resupply anchor not found')
s = s.replace(old, new)
old = '''        else if (JegAdapter.isGun(gun) && !JegAdapter.hasAmmo(gun) && JegAdapter.reserveAmmo(self, gun) <= 0\n                && findAmmoDestination(mc, self, gun) != null) state = BotState.RESUPPLY;\n'''
new = '''        else if (JegAdapter.isGun(gun) && !JegAdapter.hasAmmo(gun) && JegAdapter.reserveAmmo(self, gun) <= 0) state = BotState.RESUPPLY;\n'''
if old not in s:
    raise RuntimeError('rc4 combat resupply anchor not found')
s = s.replace(old, new)

start = s.index('    private void resupply(Minecraft mc, LocalPlayer self, ItemStack gun) {')
end = s.index('    private boolean shouldJump(', start)
old_method = s[start:end]
new_method = '''    private void resupply(Minecraft mc, LocalPlayer self, ItemStack gun) {\n        HealingAdapter.stopUse(mc);\n        release(mc);\n\n        if (!JegAdapter.isGun(gun)) {\n            BaritoneAdapter.cancel();\n            GunnerArenaAdapter.ensureBaselineLoadout(self);\n            state = BotState.SEARCH;\n            return;\n        }\n\n        if (JegAdapter.hasAmmo(gun) || JegAdapter.reserveAmmo(self, gun) > 0 || GunnerArenaAdapter.pendingAmmoArrived(self, gun)) {\n            GunnerArenaAdapter.clearAmmoGiveWait();\n            BaritoneAdapter.cancel();\n            ammoTarget = null;\n            state = JegAdapter.hasAmmo(gun) ? BotState.SEARCH : BotState.RELOAD;\n            if (state == BotState.RELOAD) reload(mc, self, gun);\n            return;\n        }\n\n        if (GunnerArenaAdapter.waitingForAmmoGive()) {\n            BaritoneAdapter.cancel();\n            return;\n        }\n        if (GunnerArenaAdapter.tryGiveRequiredAmmo(self, gun)) {\n            BaritoneAdapter.cancel();\n            return;\n        }\n\n        Entity destination = findAmmoDestination(mc, self, gun);\n        if (destination == null || !destination.isAlive()) {\n            BaritoneAdapter.cancel();\n            ammoTarget = null;\n            GunnerArenaAdapter.ensureBaselineLoadout(self);\n            state = BotState.SEARCH;\n            return;\n        }\n        double d2 = self.distanceToSqr(destination);\n        BlockPos goal = destination.blockPosition();\n        double arrival = destination instanceof ItemEntity ? AIConfig.AMMO_PICKUP_ARRIVAL_DISTANCE_SQR : 1.8;\n        if (d2 <= arrival) {\n            BaritoneAdapter.cancel();\n            releaseCombat(mc);\n            ammoRefresh = 0;\n            return;\n        }\n        if (d2 <= 4.0) {\n            BaritoneAdapter.cancel();\n            moveToward(mc, self, goal, true);\n            return;\n        }\n        if (!BaritoneAdapter.pathTo(goal, ticks % AIConfig.AMMO_PICKUP_REFRESH_TICKS == 0)) {\n            moveToward(mc, self, goal, true);\n        }\n    }\n\n'''
s = s[:start] + new_method + s[end:]
p.write_text(s)

# Version.
p = root / 'gradle.properties'
s = p.read_text()
if 'mod_version=1.5.0-rc3' not in s:
    raise RuntimeError('rc4 version anchor not found')
p.write_text(s.replace('mod_version=1.5.0-rc3', 'mod_version=1.5.0-rc4'))

(root / 'AI-GUNNER-1.5-RC4.md').write_text('''# AI Gunner 1.5 rc4\n\n- Empty gun now always enters RESUPPLY even when no ammo entity/spawner is currently visible.\n- OP fast-path: sends one `/give @s <required_ammo> 64`, waits 20 ticks, verifies reserve ammo.\n- If `/give` does not work, falls back automatically to physical ammo item / Gunner Arena ammo-spawner navigation.\n- Give attempts have a long cooldown to avoid chat/command spam.\n- Auto-shop progression: semi-auto pistol -> custom SMG -> assault rifle when affordable.\n- Existing distance-based WeaponSelector keeps switching between owned JEG guns during combat.\n- Existing post-death no-target `/play` behavior retained.\n''')
print('rc4 patch applied')
